// Parse qualification result and merge with job data
const qualification = JSON.parse($json.choices[0].message.content);
const jobData = $('Transform Job Data').item.json;

return {
  json: {
    ...jobData,
    qualified: qualification.is_qualified,
    qualification_details: qualification,
    extracted_requirements: qualification.extracted_requirements,
    rejection_reason: qualification.rejection_reason
  }
};

// Check if job already exists in Jobs Master
const currentJob = $input.first().json;
const existingJobs = $('Read Jobs Master (Dedup Check)').all().map(item => item.json);

const alreadyContacted = existingJobs.some(existing => 
  existing.job_id === currentJob.job_id && 
  existing.outreach_attempted === 'TRUE'
);

if (alreadyContacted) {
  return {
    json: {
      ...currentJob,
      skip_reason: 'Already contacted for this job',
      should_skip: true
    }
  };
}

return {
  json: {
    ...currentJob,
    should_skip: false
  }
};

// Calculate match score between resume and job
const job = $input.first().json;
const resume = $('Store Resume Data').first().json.resume;
const campaign = $('Store Resume Data').first().json.campaign;

// Parse campaign requirements
const requiredTitles = campaign.required_titles.split(',').map(t => t.trim().toLowerCase());
const avoidTitles = campaign.avoid_titles.split(',').map(t => t.trim().toLowerCase());
const requiredSkills = campaign.required_skills.split(',').map(s => s.trim().toLowerCase());
const skillsMatchType = campaign.skills_match_type; // 'partial' or 'all'
const minYearsExp = parseInt(campaign.min_years_experience);

const jobTitle = job.job_title.toLowerCase();
const jobSkills = (job.extracted_requirements.skills || []).map(s => s.toLowerCase());
const jobYearsRequired = job.extracted_requirements.years_experience || 0;
const resumeSkills = resume.skills.map(s => s.toLowerCase());

let score = 0;
let breakdown = {};

// 1. Title Match (30 points)
if (avoidTitles.some(avoid => jobTitle.includes(avoid))) {
  breakdown.title = { score: 0, reason: 'Avoid title match', matched: false };
  score += 0;
} else if (requiredTitles.some(required => jobTitle.includes(required))) {
  breakdown.title = { score: 30, reason: 'Exact title match', matched: true };
  score += 30;
} else if (requiredTitles.some(required => 
  jobTitle.includes(required.replace('senior', '').replace('junior', '').trim())
)) {
  breakdown.title = { score: 25, reason: 'Close title variation', matched: true };
  score += 25;
} else {
  breakdown.title = { score: 0, reason: 'No title match', matched: false };
}

// 2. Years of Experience (30 points)
const resumeYears = resume.total_years_experience;
if (resumeYears >= minYearsExp && resumeYears >= jobYearsRequired) {
  const yearsScore = Math.min(30, (resumeYears / Math.max(minYearsExp, jobYearsRequired, 1)) * 30);
  breakdown.experience = { score: yearsScore, resume_years: resumeYears, required: jobYearsRequired };
  score += yearsScore;
} else {
  breakdown.experience = { score: 0, resume_years: resumeYears, required: jobYearsRequired, reason: 'Insufficient experience' };
}

// 3. Education (30 points)
const hasRequiredEducation = resume.education.some(edu => 
  edu.field.toLowerCase().includes('accounting') || 
  edu.field.toLowerCase().includes('finance') ||
  edu.level.toLowerCase().includes('bachelor') ||
  edu.level.toLowerCase().includes('master')
);
if (hasRequiredEducation) {
  breakdown.education = { score: 30, reason: 'Required education met' };
  score += 30;
} else {
  breakdown.education = { score: 0, reason: 'Education requirement not met' };
}

// 4. Skills (7 points)
const matchedSkills = requiredSkills.filter(reqSkill => 
  resumeSkills.some(resSkill => resSkill.includes(reqSkill) || reqSkill.includes(resSkill))
);

if (skillsMatchType === 'all') {
  const allSkillsMatched = requiredSkills.every(reqSkill => 
    resumeSkills.some(resSkill => resSkill.includes(reqSkill) || reqSkill.includes(resSkill))
  );
  breakdown.skills = { 
    score: allSkillsMatched ? 7 : 0, 
    matched: matchedSkills, 
    required: requiredSkills,
    match_type: 'all'
  };
  score += allSkillsMatched ? 7 : 0;
} else {
  const skillScore = (matchedSkills.length / requiredSkills.length) * 7;
  breakdown.skills = { 
    score: skillScore, 
    matched: matchedSkills, 
    required: requiredSkills,
    match_type: 'partial'
  };
  score += skillScore;
}

// 5. Certifications (3 points)
const requiredCerts = (campaign.required_certifications || '').split(',').map(c => c.trim().toLowerCase()).filter(c => c);
const resumeCerts = resume.certifications.map(c => c.toLowerCase());
const matchedCerts = requiredCerts.filter(reqCert => 
  resumeCerts.some(resCert => resCert.includes(reqCert))
);

if (requiredCerts.length > 0) {
  const certScore = (matchedCerts.length / requiredCerts.length) * 3;
  breakdown.certifications = { 
    score: certScore, 
    matched: matchedCerts, 
    required: requiredCerts 
  };
  score += certScore;
} else {
  breakdown.certifications = { score: 0, reason: 'No certifications required' };
}

// Classification
let classification = 'No Fit';
if (score >= 75) classification = 'Hard Fit';
else if (score >= 50) classification = 'Soft Fit';

return {
  json: {
    ...job,
    match_score: Math.round(score),
    classification: classification,
    score_breakdown: breakdown,
    resume_data: resume,
    campaign_data: campaign
  }
};

