const outreachData = JSON.parse($json.choices[0].message.content);
const jobData = $('Process Lead Data').first().json;

return {
  json: {
    ...jobData,
    outreach: outreachData
  }
};

// Aggregate all results for summary
const allJobs = $('Transform Job Data').all();
const qualified = $('Filter: Only Qualified Jobs').all();
const newJobs = $('Filter: New Jobs Only').all();
const hardFits = newJobs.filter(j => j.json.classification === 'Hard Fit');
const softFits = newJobs.filter(j => j.json.classification === 'Soft Fit');
const outreachSent = $('Log Outreach').all();
const emailsSent = outreachSent.filter(o => o.json.outreach_channel === 'email');
const linkedinSent = outreachSent.filter(o => o.json.outreach_channel === 'linkedin');
const rejections = $('Log Rejections to Sheet').all();

const summary = {
  execution_date: new Date().toISOString(),
  total_jobs_scraped: allJobs.length,
  qualified_jobs: qualified.length,
  new_jobs: newJobs.length,
  hard_fits: hardFits.length,
  soft_fits: softFits.length,
  rejections: rejections.length,
  outreach_sent: outreachSent.length,
  emails_sent: emailsSent.length,
  linkedin_sent: linkedinSent.length,
  top_matches: outreachSent.slice(0, 5).map(o => ({
    company: o.json.company_name,
    title: o.json.job_title,
    score: o.json.match_score,
    classification: o.json.classification
  }))
};

return { json: summary };

